Overview of all notes

```dataviewjs
const reviewedKey = "reviewed?";
const typeKey = "type";
const typeValue = "synthesis";

const current = dv.current();
const baseFolder = current.file.folder ?? "";
const prefix = baseFolder ? `${baseFolder}/` : "";

// All immediate child folders under the current note's folder
const childFolders = [...new Set(
  app.vault.getMarkdownFiles()
    .map(f => f.path)
    .filter(path => path.startsWith(prefix))
    .map(path => path.slice(prefix.length))
    .filter(rest => rest.includes("/"))
    .map(rest => `${prefix}${rest.split("/")[0]}`)
)].sort((a, b) => a.localeCompare(b));

const rows = childFolders.map(folder => {
  const pages = dv.pages(`"${folder}"`).array();

  const total = pages.length;
  const reviewedTrue = pages.filter(p => p[reviewedKey] === true).length;
  const synthesis = pages.filter(p => p[typeKey] === typeValue).length;
  const both = pages.filter(
    p => p[reviewedKey] === true && p[typeKey] === typeValue
  ).length;

  return [
    folder.replace(prefix, ""),
    total,
    reviewedTrue,
    synthesis,
    both,
    total ? `${Math.round((both / total) * 100)}%` : "0%"
  ];
});

// Unique pages across all child folders
const allPages = childFolders.flatMap(folder => dv.pages(`"${folder}"`).array());
const uniquePages = Array.from(new Map(allPages.map(p => [p.file.path, p])).values());

const grandTotal = uniquePages.length;
const grandReviewed = uniquePages.filter(p => p[reviewedKey] === true).length;
const grandSynthesis = uniquePages.filter(p => p[typeKey] === typeValue).length;
const grandBoth = uniquePages.filter(
  p => p[reviewedKey] === true && p[typeKey] === typeValue
).length;

dv.header(2, `Folder list`);

if (rows.length === 0) {
  dv.paragraph("No child folders with notes found.");
} else {
  dv.table(
    ["Folder", "Notes", "reviewed? = true", 'type = "synthesis"', "Both", "% both"],
    rows
  );

const reviewedPct = grandTotal ? `${Math.round((grandReviewed / grandTotal) * 100)}%` : "0%";
const synthesisPct = grandTotal ? `${Math.round((grandSynthesis / grandTotal) * 100)}%` : "0%";
const bothPct = grandTotal ? `${Math.round((grandBoth / grandTotal) * 100)}%` : "0%";

dv.paragraph(
  `**Overall:** ${grandBoth} / ${grandTotal} notes are both reviewed and synthesis (${bothPct})` +
  ` · reviewed: ${grandReviewed} / ${grandTotal} (${reviewedPct})` +
  ` · synthesis: ${grandSynthesis} / ${grandTotal} (${synthesisPct})`
);
}
```

